#!/usr/bin/env node
// Helper for calling the Slack Web API.
//
// Usage:
//   node slack_request.cjs <endpoint> [--body '{"json":...}'] [--token xoxb-...] [--method GET|POST]
//
// The token falls back to the SLACK_TOKEN environment variable.
// Output is LLM-friendly JSON: the parsed response with http_status added.
// Exit code is non-zero when the call fails (network, bad args, or ok:false).

const endpoint = process.argv[2];
const args = process.argv.slice(3);

function parseArgs(argv) {
  const out = { body: undefined, token: undefined, method: "POST", help: false };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === "--body") out.body = argv[++i];
    else if (argv[i] === "--token") out.token = argv[++i];
    else if (argv[i] === "--method") out.method = String(argv[++i]).toUpperCase();
    else if (argv[i] === "--help" || argv[i] === "-h") out.help = true;
    else {
      console.error(`Unknown argument: ${argv[i]}`);
      process.exit(2);
    }
  }
  return out;
}

async function main() {
  if (typeof fetch !== "function") {
    console.error("Error: Node.js 18+ is required (global fetch)");
    process.exit(1);
  }

  const opts = parseArgs(args);
  if (opts.help || !endpoint) {
    console.log(
      "Usage: node slack_request.cjs <endpoint> [--body '{\"json\":...}'] [--token xoxb-...] [--method GET|POST]\n" +
        "Token falls back to SLACK_TOKEN env var. Base URL: https://slack.com/api"
    );
    process.exit(endpoint ? 0 : 2);
  }

  const token = opts.token || process.env.SLACK_TOKEN;
  if (!token) {
    console.error("Error: no token. Pass --token or set SLACK_TOKEN.");
    process.exit(2);
  }

  const url = `https://slack.com/api/${endpoint}`;
  const headers = { Authorization: `Bearer ${token}` };
  let payload;
  if (opts.body !== undefined) {
    headers["Content-Type"] = "application/json; charset=utf-8";
    payload = JSON.stringify(JSON.parse(opts.body)); // validate and normalize JSON
  }

  const res = await fetch(url, { method: opts.method, headers, body: payload });
  const text = await res.text();
  let json;
  try {
    json = JSON.parse(text);
  } catch {
    json = { raw: text };
  }
  if (res.status === 429) {
    console.error(`Rate limited. Retry-After: ${res.headers.get("Retry-After")}`);
  }
  console.log(JSON.stringify({ http_status: res.status, ...json }, null, 2));
  process.exit(json.ok === false ? 1 : 0);
}

main().catch((err) => {
  console.error(`Error: ${err.message}`);
  process.exit(1);
});

// Task-local verification harness for .codex/skills/slack-api/scripts/slack_request.cjs
// Checks syntax (node --check) and exercises offline paths (usage, token check, JSON validation).
const { spawnSync } = require("node:child_process");
const path = require("node:path");

const script = path.join(__dirname, ".codex", "skills", "slack-api", "scripts", "slack_request.cjs");

let failed = 0;

// 1. Syntax check
const syntax = spawnSync(process.execPath, ["--check", script], { encoding: "utf8" });
const syntaxOk = syntax.status === 0;
console.log(`${syntaxOk ? "PASS" : "FAIL"} syntax check (node --check)`);
if (syntax.stderr) console.log("  ", syntax.stderr.trim());
if (!syntaxOk) failed++;

// 2. Behavior checks (offline: no token, no network)
const cases = [
  { argv: ["api.test"], expect: 2, label: "missing token -> usage error exit 2" },
  { argv: ["chat.postMessage", "--body", "{bad json"], expect: 1, label: "invalid JSON body -> error exit 1" },
  { argv: ["api.test", "--help"], expect: 0, label: "--help with endpoint -> usage exit 0" },
  { argv: [], expect: 2, label: "no args -> usage exit 2" },
];

for (const c of cases) {
  const r = spawnSync(process.execPath, [script, ...c.argv], { encoding: "utf8" });
  const ok = r.status === c.expect;
  console.log(`${ok ? "PASS" : "FAIL"} ${c.label} (status=${r.status}, expected ${c.expect})`);
  const line = (r.stderr || r.stdout || "").trim().split("\n")[0];
  if (line) console.log("  first line:", line);
  if (!ok) failed++;
}

process.exit(failed ? 1 : 0);

